const CTEA_REGIONS = {"zhejiang": {"jp": "浙江省", "en": "ZHEJIANG", "label": [120.1, 29.6], "short": "浙江", "desc": "杭州を中心とする、中国を代表する緑茶の産地。西湖龍井や安吉白茶の故郷。", "pick": "浙江"}, "jiangsu": {"jp": "江蘇省", "en": "JIANGSU", "label": [119.9, 31.9], "short": "江蘇", "desc": "太湖のほとり。螺旋状にくるっと巻いた繊細な緑茶、洞庭碧螺春の産地。", "pick": "江蘇"}, "anhui": {"jp": "安徽省", "en": "ANHUI", "label": [117.6, 30.6], "short": "安徽", "desc": "黄山のふもと。黄山毛峰、太平猴魁、六安瓜片などの銘茶と、紅茶の祁門紅茶が生まれる。", "pick": "安徽"}, "wuyi": {"jp": "福建・武夷山", "en": "WUYI", "label": [117.98, 27.7], "short": "武夷山", "desc": "福建省北部の世界遺産の山。岩場で育つ「岩茶」と呼ばれる焙煎の効いた烏龍茶と、紅茶の発祥とされる正山小種の産地。", "pick": "福建"}, "anxi": {"jp": "福建・安渓", "en": "ANXI", "label": [118.18, 25.05], "short": "安渓", "desc": "福建省南部。花のように香る烏龍茶、鉄観音の故郷。", "pick": "福建"}, "fuding": {"jp": "福建・福鼎と福州", "en": "FUDING & FUZHOU", "label": [120.2, 27.3], "short": "福鼎", "desc": "福建省北東部の福鼎は白茶の故郷。省都の福州はジャスミン茶の発祥の地とされる。", "pick": "福建"}, "guangdong": {"jp": "広東省（潮州）", "en": "GUANGDONG", "label": [116.6, 23.8], "short": "潮州", "desc": "潮州の鳳凰山では、一本一本の木ごとに香りが違うといわれる鳳凰単叢が作られる。潮州は工夫茶の文化の本場。", "pick": "広東"}, "yunnan": {"jp": "雲南省", "en": "YUNNAN", "label": [100.8, 22.8], "short": "雲南", "desc": "茶樹の原産地のひとつとされる南西部。樹齢数百年の古い茶樹も残り、プーアル茶と滇紅の産地。", "pick": "雲南"}, "sichuan": {"jp": "四川省", "en": "SICHUAN", "label": [103.0, 30.0], "short": "四川", "desc": "中国で最も古い茶の栽培の記録が残る土地のひとつ。蒙頂山の緑茶や黄茶が名高い。", "pick": "四川"}, "hunan": {"jp": "湖南省", "en": "HUNAN", "label": [111.6, 28.4], "short": "湖南", "desc": "洞庭湖に浮かぶ君山島の黄茶、君山銀針と、安化県の黒茶の産地。", "pick": "湖南"}, "guangxi": {"jp": "広西", "en": "GUANGXI", "label": [110.5, 23.4], "short": "広西", "desc": "梧州の六堡茶は、湿度の高い気候で熟成させる黒茶。", "pick": "広西"}, "henan": {"jp": "河南省（信陽）", "en": "HENAN", "label": [114.1, 32.1], "short": "信陽", "desc": "茶どころの北の端にあたる信陽。寒い冬を越えて育つ茶葉で作る信陽毛尖が名高い。", "pick": "河南"}, "taiwan": {"jp": "台湾", "en": "TAIWAN", "label": [120.95, 23.7], "desc": "標高の高い山で作られる「高山茶」をはじめ、香り高い烏龍茶の宝庫。発酵の軽い清香系から、東方美人のような蜜の香りのお茶まで多彩。", "pick": "台湾"}};
const CTEA_COUNTRIES = {"china": {"jp": "中国・台湾", "style": "中国茶", "en": "CHINA & TAIWAN", "map": "tea_china", "callout": true, "regions": ["zhejiang", "jiangsu", "anhui", "wuyi", "anxi", "fuding", "guangdong", "yunnan", "sichuan", "hunan", "guangxi", "henan", "taiwan"], "desc": "中国茶は、発酵の度合いによって緑茶・白茶・黄茶・青茶（烏龍茶）・紅茶・黒茶の「六大茶類」に分けられる。地図の産地をタップすると、その土地のお茶が表示される。"}};
const CTEA_TYPES = [{"id": "green", "name": "緑茶", "en": "Green Tea", "kind": "六大茶類", "home": "浙江、江蘇、安徽、四川、河南", "p": [2, 1, 3, 2, 1, 0, 5, 2], "tags": ["豆の香り", "爽やか", "若葉"], "brew": {"t": "75〜85℃", "m": "1〜2分", "g": "3g", "ml": "150ml", "note": "耐熱グラスに茶葉を入れてお湯を注ぎ、茶葉が開いて沈んでいく様子も楽しむ。"}, "desc": "摘んだ茶葉を釜で炒る（殺青）などして、発酵させずに作るお茶。中国で最も多く飲まれている。日本の緑茶の多くが「蒸す」のに対し、中国では「炒る」ものが多く、栗や豆のような香ばしい香りが出る。"}, {"id": "white", "name": "白茶", "en": "White Tea", "kind": "六大茶類", "home": "福建（福鼎・政和）", "p": [3, 3, 4, 0, 0, 1, 3, 1], "tags": ["蜜", "干し草", "やさしい"], "brew": {"t": "85〜95℃", "m": "2〜3分", "g": "4g", "ml": "150ml", "note": "熟成した白茶は熱湯で煮出してもおいしい。"}, "desc": "摘んだ芽や葉を、もまずに自然にしおれさせて乾かすだけの、もっとも手を加えないお茶。わずかに発酵し、やさしい甘さと干し草や蜜のような香り。数年寝かせると味わいが深まる。"}, {"id": "yellow", "name": "黄茶", "en": "Yellow Tea", "kind": "六大茶類", "home": "湖南、四川、安徽", "p": [2, 2, 4, 1, 1, 1, 3, 2], "tags": ["まろやか", "甘い", "珍しい"], "brew": {"t": "80〜85℃", "m": "2分", "g": "3g", "ml": "150ml", "note": ""}, "desc": "緑茶とほぼ同じ作り方だが、途中で茶葉を包んで蒸らす「悶黄（もんおう）」という工程を加え、ゆっくり軽く発酵させたお茶。青臭さが抜けてまろやか。生産量が少ない。"}, {"id": "oolong", "name": "青茶（烏龍茶）", "en": "Oolong Tea", "kind": "六大茶類", "home": "福建（武夷山・安渓）、広東、台湾", "p": [4, 3, 3, 2, 3, 1, 3, 3], "tags": ["花", "果実", "焙煎香"], "brew": {"t": "95〜100℃", "m": "30秒〜1分（何煎も淹れる）", "g": "5〜7g", "ml": "120ml", "note": "小さな茶壺や蓋碗に茶葉をたっぷり入れ、短い時間で何煎も淹れる「工夫茶」で楽しみたい。"}, "desc": "茶葉を揺すって縁を傷つけ、部分的に発酵させて作るお茶。発酵の度合いや焙煎の強さで、緑茶に近い花の香りのものから、紅茶に近い熟した果実の香りのものまで幅広い。"}, {"id": "black", "name": "紅茶", "en": "Black Tea", "kind": "六大茶類", "home": "福建、安徽、雲南", "p": [2, 3, 4, 2, 1, 1, 2, 4], "tags": ["甘い", "蜜", "まろやか"], "brew": {"t": "95〜100℃", "m": "1〜3分", "g": "3〜5g", "ml": "150ml", "note": ""}, "desc": "茶葉を完全に発酵させたお茶。中国では水色の色から「紅茶」と呼ぶ。中国紅茶は渋みが少なく、蜜や芋のような甘い香りのものが多い。"}, {"id": "dark", "name": "黒茶", "en": "Dark Tea", "kind": "六大茶類", "home": "雲南（普洱）、湖南（安化）、広西（六堡）", "p": [0, 1, 3, 1, 1, 5, 0, 5], "tags": ["熟成", "土", "まろやか"], "brew": {"t": "100℃", "m": "10〜30秒（何煎も淹れる）", "g": "5〜8g", "ml": "150ml", "note": "最初の一煎は茶葉を洗うために捨てる（洗茶）のが一般的。"}, "desc": "茶葉を微生物の力で発酵させる「後発酵茶」。固めて長く熟成させるものが多く、年月を経るほど味わいがまろやかになり、価値が上がるものもある。"}, {"id": "flower", "name": "花茶", "en": "Flower Tea", "kind": "再加工茶", "home": "福建（福州）、広西（横県）", "p": [5, 1, 3, 1, 0, 0, 4, 1], "tags": ["ジャスミン", "華やか"], "brew": {"t": "85〜90℃", "m": "2〜3分", "g": "3g", "ml": "200ml", "note": ""}, "desc": "緑茶などに花の香りを何度も吸わせて作るお茶。ジャスミン茶（茉莉花茶）が代表。"}];
